  q=[(r,c)];seen.add((r,c)); cells=[]
  while q:
   a,b=q.pop();cells.append((a,b))
   for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
    nr,nc=a+da,b+db
    if 0<=nr<R and 0<=nc<C and grid[nr][nc]==v and (nr,nc) not in seen:
     seen.add((nr,nc));q.append((nr,nc))
  comps4.append((v,cells))
from collections import defaultdict
by=defaultdict(list)
for v,cells in comps4:by[shape(cells)].append((v,cells))
for shp,items in by.items():
 if len(items)>1:
