def norm(cells,rot=0,reflect=False):
 pts=[]
 for r,c in cells:
  x,y=r,c
  if reflect:y=-y
  for _ in range(rot): x,y=y,-x
  pts.append((x,y))
 mnx=min(x for x,y in pts);mny=min(y for x,y in pts)
 return frozenset((x-mnx,y-mny) for x,y in pts)
